<script setup>
import { computed, ref } from 'vue';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import { data, ui, go, addAgent, commit, notify } from '../lib/store.js';
const query = ref(''), modal = ref(false), editingId = ref(null), removing = ref(null);
const blank = () => ({ name: '', description: '', instructions: '', type: 'chat', icon: 'Bot' });
const form = ref(blank());
const presets = [
  { name: '技术方案助手', description: '从业务需求到系统设计，把关键决策写清楚。', instructions: '请协助我分析业务需求，梳理模块职责、数据流转、技术取舍与验收标准。结论要注明假设，不编造现有系统的信息。', type: 'document', icon: 'Code2', capability: '需求分析 · 方案编写' },
  { name: '知识整理助手', description: '提炼长文档的重点，连接零散的知识与想法。', instructions: '请根据我提供的资料提炼核心观点，区分事实与推断，并列出仍需确认的问题。没有资料时先说明信息缺口。', type: 'chat', icon: 'BookOpen', capability: '阅读理解 · 资料归纳' },
  { name: '任务规划助手', description: '拆解复杂目标，让下一步行动清晰可见。', instructions: '请将我的目标拆成具体任务，说明依赖、优先级与可验证的完成标准。不要编造时间估算和负责人。', type: 'table', icon: 'Layers', capability: '目标拆解 · 任务规划' },
];
const agents = computed(() => data.agents.filter(a => a.name.toLowerCase().includes(query.value.toLowerCase())));
function open(agent, id = null) { editingId.value = id; form.value = agent ? { ...agent } : blank(); modal.value = true; }
function save() { if (!form.value.name.trim() || !form.value.instructions.trim()) return; const value = { ...form.value, name: form.value.name.trim() }; const ok = editingId.value ? commit(d => { const i = d.agents.findIndex(a => a.id === editingId.value); if (i >= 0) d.agents[i] = { ...value, id: editingId.value }; }) : addAgent(value); if (ok) { modal.value = false; notify('智能体配置已保存到本地'); } }
function use(agent) { ui.draft = agent.instructions; go(agent.type === 'chat' ? 'chat' : 'office'); }
</script>
<template>
  <div class="page agents-page"><header class="page-heading"><div><span class="small-label">为你的工作，定义专长</span><h1>智能体</h1><p>把重复的工作方式，交给一个熟悉它的助手。</p></div><button class="primary-button" @click="open()"><Icon name="Plus" :size="16" />创建智能体</button></header>
    <section class="agent-intro-panel"><div><span class="feature-label"><Icon name="Bot" :size="15" />为工作量身定制</span><h2>每一种工作，都可以有专属助手。</h2><p>定义它的职责与输出方式。下一次，从熟悉的上下文开始。</p></div><div class="agent-intro-flow" aria-label="定义职责、连接知识、开始协作"><span><Icon name="AlignLeft" :size="19" />定义职责</span><Icon name="ChevronRight" :size="14" /><span><Icon name="BookOpen" :size="19" />参考资料</span><Icon name="ChevronRight" :size="14" /><span><Icon name="Sparkles" :size="19" />开始协作</span></div></section>
    <section><div class="section-heading"><div><h2>从一个模板开始</h2><span class="section-caption">选择后可按你的工作方式修改</span></div><span class="subtle-tag">配置示例</span></div><div class="agent-grid"><article v-for="preset in presets" :key="preset.name" class="agent-card"><div class="agent-card-top"><span class="agent-icon"><Icon :name="preset.icon" :size="22" /></span><span class="subtle-tag">模板</span></div><h3>{{ preset.name }}</h3><p>{{ preset.description }}</p><div class="agent-card-bottom"><span>{{ preset.capability }}</span><button class="text-button" @click="open(preset)">使用模板 <Icon name="ArrowUpRight" :size="15" /></button></div></article></div></section>
    <section class="my-agents"><div class="section-heading"><div><h2>我的智能体 <span class="heading-count">{{ data.agents.length }}</span></h2><span class="section-caption">保存在当前浏览器的助手配置</span></div><label class="search-field"><Icon name="Search" :size="15" /><input v-model="query" placeholder="搜索智能体…" aria-label="搜索智能体" /></label></div><div v-if="agents.length" class="agent-grid"><article v-for="agent in agents" :key="agent.id" class="agent-card"><div class="agent-card-top"><span class="agent-icon"><Icon :name="agent.icon" :size="22" /></span><div><button class="icon-button" :aria-label="'编辑 ' + agent.name" @click="open(agent, agent.id)"><Icon name="Pencil" :size="15" /></button><button class="icon-button" :aria-label="'删除 ' + agent.name" @click="removing = agent"><Icon name="Trash2" :size="15" /></button></div></div><h3>{{ agent.name }}</h3><p>{{ agent.description || '尚未添加描述' }}</p><div class="agent-card-bottom"><span>本地配置</span><button class="text-button" @click="use(agent)">开始对话 <Icon name="ArrowRight" :size="15" /></button></div></article></div><div v-else class="empty-inline my-agents-empty"><Icon name="Bot" :size="25" /><span>{{ query ? '没有找到匹配的智能体' : '还没有自己的助手，从上面的模板开始吧。' }}</span></div></section>
    <footer class="page-footer"><span><Icon name="Eye" :size="13" />本地设计预览 · 配置可保存，模型执行尚未接入</span></footer>
  </div><Modal v-if="modal" :title="editingId ? '编辑智能体' : '创建你的智能体'" @close="modal = false"><form class="form-stack" @submit.prevent="save"><label>名称<input v-model="form.name" required maxlength="40" autofocus placeholder="例如：技术方案助手" /></label><label>一句话描述<input v-model="form.description" maxlength="120" placeholder="它可以帮你完成什么？" /></label><label>职责与指令<textarea v-model="form.instructions" rows="5" maxlength="5000" required placeholder="描述它的专长、工作方法和输出要求…" /></label><label>主要工作方式<select v-model="form.type"><option value="chat">自由对话</option><option value="document">文档写作</option><option value="diagram">图表梳理</option><option value="table">任务规划</option></select></label><p class="muted small">保存后可将指令带入新对话。当前为界面预览，不会调用模型。</p><div class="modal-actions"><button type="button" class="secondary-button" @click="modal = false">取消</button><button class="primary-button">保存智能体</button></div></form></Modal>
  <Modal v-if="removing" title="删除智能体" @close="removing = null"><p>删除「{{ removing.name }}」的本地配置？已有对话会保留。</p><div class="modal-actions"><button class="secondary-button" @click="removing = null">取消</button><button class="danger-button" @click="commit(d => d.agents = d.agents.filter(a => a.id !== removing.id)); removing = null">删除配置</button></div></Modal>
</template>
